"""The ingestion seam: the canonical ``SourceDocument`` a corpus feeds in.

A ``SourceDocument`` is a *whole* document (not pre-chunked) handed to the
retrieval pipeline. Any data source — the docs repo today, skills/tools/history
later — adapts its native records into this one shape, so chunking, embedding,
and indexing never need to know where a document came from.
"""

from enum import Enum
from typing import Any, Dict, Optional

from pydantic import BaseModel, Field


class ContentType(str, Enum):
    """Kind of content a document holds; selects per-type retrieval defaults."""

    MARKDOWN = "markdown"
    SKILL = "skill"
    TOOL = "tool"
    CODE = "code"


class SourceDocument(BaseModel):
    """A whole source document to be indexed for retrieval."""

    id: str = Field(description="Stable, source-owned id (used for sync/dedup).")
    title: str
    content: str = Field(description="Full document body — not pre-chunked.")
    source: str = Field(description="Originating corpus/connector, e.g. 'rasa-docs'.")
    content_type: ContentType = ContentType.MARKDOWN
    url: Optional[str] = Field(default=None, description="Canonical URL, if any.")
    version: Optional[str] = Field(
        default=None,
        description="Content hash/version; drives incremental sync (Phase 2).",
    )
    metadata: Dict[str, Any] = Field(default_factory=dict)
